#include <bits/stdc++.h>
#define int long long
using namespace std;

int32_t main() {
    int t;
    cin>>t;
    
    while(t--){
        int n,m;
        cin>>n>>m;
        
        vector<int> v(m);
        for(int i=0;i<m;i++){
            cin>>v[i];
        }
        sort(v.begin(),v.end());
    
        vector<int> temp1(m),temp2(m);
        for(int i=0;i<m;i++){
            temp1[i]=v[i]-v[0]+1;
            temp2[i]=v[i]+n-v[m-1];
        }
        
        // for(int i=0;i<m;i++){
        //     cout<<temp1[i]<<" ";
        // }
        // cout<<endl;
        // for(int i=0;i<m;i++){
        //     cout<<temp2[i]<<" ";
        // }
        // cout<<endl;
        
        int ans=0;
        for(int i=0;i<m-1;i++){
            if(temp1[i+1]>temp2[i]){
                ans=max(ans,temp1[i+1]-temp2[i]-1);
            }
        }
        ans+=min(2*(v[0]-1)+(n-v[m-1]),(v[0]-1)+2*(n-v[m-1]));
        cout<<ans<<endl;
    }

}
